(37361, 'Proverbs 16:9', 'Proverbs', 16, 9, 'انسان په زړه کې ځان ته د تګ لارې جوړوي خو څښتن د هغه د قدمونو لارښوونه کوي.', 'انسان په زره کې جان ته د تګ لارې جوروی خو چشتن د هغه د قدمونو لارشوونه کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_009.mp3', 'https://drive.google.com/file/d/115JBfRU96FPDfSkH9rgvJSm69OcXxUnj/preview', 1761237839, 1761237839),
(37362, 'Proverbs 16:10', 'Proverbs', 16, 10, 'د پاچا خبرې د الهام په څېر دي او په قضاوت کې هېڅ بې‌انصافي نه کوي.', 'د پاچا خبرې د الهام په چېر دی او په قضاوت کې هېچ بې‌انصافی نه کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_010.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1HMjbAbikzoWGRd4YVQPp1z2xrPbBt24C&export=download', 1761237839, 1761237839),
(37363, 'Proverbs 16:11', 'Proverbs', 16, 11, 'سمه تله او تول د څښتن د قضاوت نښه ده او د وزن کولو دپاره یې ټول کاڼي جوړ کړي دي.', 'سمه تله او تول د چشتن د قضاوت نشه ده او د وزن کولو دپاره یې تول کانی جور کری دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_011.mp3', 'https://drive.google.com/file/d/1AmRlg_SaWsWlIJYBjqEVFvjDwUt8JgD9/preview', 1761237839, 1761237839),
(37364, 'Proverbs 16:12', 'Proverbs', 16, 12, 'پاچاهان د بدو کارونو نه کرکه کوي ځکه د پاچاهۍ تخت یې د عدالت په بنیاد ولاړ دی.', 'پاچاهان د بدو کارونو نه کرکه کوی جکه د پاچاهی تخت یې د عدالت په بنیاد ولار دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_012.mp3', 'https://drive.google.com/file/d/1Io1b0NGlRNPpNyqVZKDm0Aa9HjOYaCCL/preview', 1761237839, 1761237839),
(37365, 'Proverbs 16:13', 'Proverbs', 16, 13, 'پاچاهان په رښتینو خبرو خوشحالیږي او له هغه چا سره مینه کوي چې رښتیا وایي.', 'پاچاهان په رشتینو خبرو خوشحالیزی او له هغه چا سره مینه کوی چې رشتیا وایی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_013.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1Zw9GbsltN6BqYCq1RFuLInkpvk3i2Y1K&export=download', 1761237839, 1761237839),
(37366, 'Proverbs 16:14', 'Proverbs', 16, 14, 'د پاچا غوسه د مرګ پیغام دی خو د حکمت خاوند د هغه قهر سړوي.', 'د پاچا غوسه د مرګ پیغام دی خو د حکمت خاوند د هغه قهر سروی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_014.mp3', 'https://drive.google.com/file/d/1zUw-NTh1K54dNW0hvSE07lgToVcbddMO/preview', 1761237839, 1761237839),
(37367, 'Proverbs 16:15', 'Proverbs', 16, 15, 'د پاچا په ورین تندي کې د ژوندون زېری وي او رحم یې د پسرلي د ورېځې په څېر باران وروي.', 'د پاچا په ورین تندی کې د ژوندون زېری وی او رحم یې د پسرلی د ورېجې په چېر باران وروی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_015.mp3', 'https://drive.google.com/file/d/1YWTNOR8Pry7PUsNbenS09deElx_dqmVx/preview', 1761237839, 1761237839),
(37368, 'Proverbs 16:16', 'Proverbs', 16, 16, 'د حکمت حاصلول له سرو زرو نه څو چنده بهتر دي او عقل لاسته راوړل له سپینو زرو نه غوره دي.', 'د حکمت حاصلول له سرو زرو نه چو چنده بهتر دی او عقل لاسته راورل له سپینو زرو نه غوره دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_016.mp3', 'https://drive.google.com/file/d/1Zxugj6hIgYcpbkCUbYKVZWI9t8wJ9kT_/preview', 1761237839, 1761237839),
(37369, 'Proverbs 16:17', 'Proverbs', 16, 17, 'د صادقانو سمه لار انسان د بدۍ او بلا نه ساتي څوک چې خپلې لارې ته پام کوي نو خپل ځان ساتي.', 'د صادقانو سمه لار انسان د بدی او بلا نه ساتی چوک چې خپلې لارې ته پام کوی نو خپل جان ساتی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_017.mp3', 'https://drive.google.com/file/d/1MwtB6OcIlZzaKCqTMcPOGYHlwkKrOIie/preview', 1761237839, 1761237839),
(37370, 'Proverbs 16:18', 'Proverbs', 16, 18, 'مغرور تباه کیږي کبرجن راغورځیږي.', 'مغرور تباه کیزی کبرجن راغورجیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_018.mp3', 'https://drive.google.com/file/d/16EAnWB6dy2vv_pP1X24_TB4SRBfkT7W8/preview', 1761237839, 1761237839),
(37371, 'Proverbs 16:19', 'Proverbs', 16, 19, 'ښه ده چې انسان عاجز وي او د غریبانو سره اړیکې ولري له دې نه چې د مغرورانو سره په غنیمت کې شریک شي.', 'شه ده چې انسان عاجز وی او د غریبانو سره اریکې ولری له دې نه چې د مغرورانو سره په غنیمت کې شریک شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_019.mp3', 'https://drive.google.com/file/d/1rYDuW6aG1C67YAvmZsbsaoX7eztp1f7V/preview', 1761237839, 1761237839),
(37372, 'Proverbs 16:20', 'Proverbs', 16, 20, 'بریالی دی هغه څوک چې کلام اوري او بختور دی هغه چې په څښتن باور کوي.', 'بریالی دی هغه چوک چې کلام اوری او بختور دی هغه چې په چشتن باور کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_020.mp3', 'https://drive.google.com/uc?id=14bcyRPmfQlVVFUd1b6wKe6d2naOz2naB&export=download', 1761237839, 1761237839),
(37373, 'Proverbs 16:21', 'Proverbs', 16, 21, 'د حکمت خاوند له خپل عقل څخه پېژندل کیږي او خوږه ژبه په زده کړه کې ډېره قناعت بخښونکې وي.', 'د حکمت خاوند له خپل عقل چخه پېژندل کیزی او خوزه ژبه په زده کره کې دېره قناعت بخشونکې وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_021.mp3', 'https://drive.google.com/file/d/1YeX5xH2rTIPNmLjSRjIWF60w8x6_tsXC/preview', 1761237839, 1761237839),
(37374, 'Proverbs 16:22', 'Proverbs', 16, 22, 'څوک چې هوښیاري لري هغه یې د ژوند سرچینه ده خو جهالت د جاهلانو دپاره د سزا لښته ده.', 'چوک چې هوشیاری لری هغه یې د ژوند سرچینه ده خو جهالت د جاهلانو دپاره د سزا لشته ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_022.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=113ka-EqznIByzdxa1epj9NzSdu25Z90b&export=download', 1761237839, 1761237839),
(37375, 'Proverbs 16:23', 'Proverbs', 16, 23, 'د حکمت د خاوند زړه د هغه ژبه هوښیاروي چې هرې خبرې ته یې په قناعت ورکولو کې ګټه رسوي.', 'د حکمت د خاوند زره د هغه ژبه هوشیاروی چې هرې خبرې ته یې په قناعت ورکولو کې ګته رسوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_023.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1az4lV-GOZMCvhOpUaQ2HaYS2I8Z0EeCR&export=download', 1761237839, 1761237839),
(37376, 'Proverbs 16:24', 'Proverbs', 16, 24, 'مهربانې خبرې د شاتو د مچیو د ډک چک په شان دي چې د روح دپاره خواږه او د بدن دپاره شفا ده.', 'مهربانې خبرې د شاتو د مچیو د دک چک په شان دی چې د روح دپاره خوازه او د بدن دپاره شفا ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_024.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1ehmsp5Cg9-Nqwh-0-7dAUzdjBbUNjqwi&export=download', 1761237839, 1761237839),
(37377, 'Proverbs 16:25', 'Proverbs', 16, 25, 'د یو انسان په نظر یوه لار سمه ښکاري خو په اخر کې هغه په مرګ پای ته رسیږي.', 'د یو انسان په نظر یوه لار سمه شکاری خو په اخر کې هغه په مرګ پای ته رسیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_025.mp3', 'https://drive.google.com/file/d/1UnE0Hl6yqLyst9MvMEF6JA6RQlMr370a/preview', 1761237839, 1761237839),
(37378, 'Proverbs 16:26', 'Proverbs', 16, 26, 'د یو مزدور لوږه هغه سخت کار ته مجبوروي او وږې ګېډه سړی نور ډېر کار ته هڅوي.', 'د یو مزدور لوزه هغه سخت کار ته مجبوروی او وزې ګېده سری نور دېر کار ته هچوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_026.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=12KQ1S8YjxPUDFiB2Bc62eG4KFPoxQ0q2&export=download', 1761237839, 1761237839),
(37379, 'Proverbs 16:27', 'Proverbs', 16, 27, 'بېکاره انسان بدې نقشې جوړوي او خبرې یې د اور په شان سوځول کوي.', 'بېکاره انسان بدې نقشې جوروی او خبرې یې د اور په شان سوجول کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_027.mp3', 'https://drive.google.com/file/d/1dBBmuIrDzXVAguQOFbNfY6wPBo1XMQzI/preview', 1761237839, 1761237839),
(37380, 'Proverbs 16:28', 'Proverbs', 16, 28, 'بې‌لارې سړی شخړو ته لمن وهي او غیبت کوونکی نژدې دوستان جدا کوي.', 'بې‌لارې سری شخرو ته لمن وهی او غیبت کوونکی نژدې دوستان جدا کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_028.mp3', 'https://drive.google.com/file/d/1RjxEtGJfsFlv1epbYunpNwvbkWXTYs5e/preview', 1761237839, 1761237839),
(37381, 'Proverbs 16:29', 'Proverbs', 16, 29, 'ظالم خپل ملګری بې‌لارې کوي او بدې لارې ته یې هڅوي.', 'ظالم خپل ملګری بې‌لارې کوی او بدې لارې ته یې هچوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_029.mp3', 'https://drive.google.com/uc?id=1Mbyv4hDcPAd0K8VfJe3gpzy_VoXvmEXQ&export=download', 1761237839, 1761237839),
(37382, 'Proverbs 16:30', 'Proverbs', 16, 30, 'څوک چې سترګې او وروځې وهي بدې نقشې جوړوي او د شونډو په چیچلو نورو ته تاوان رسوي.', 'چوک چې سترګې او وروجې وهی بدې نقشې جوروی او د شوندو په چیچلو نورو ته تاوان رسوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_030.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1NohFGIqE0UWQtLID7D4G_5ETlrNM73j8&export=download', 1761237839, 1761237839),
(37383, 'Proverbs 16:31', 'Proverbs', 16, 31, 'سپین ویښته د عزت تاج دی چې د صداقت له لارې تر‌لاسه کیږي.', 'سپین ویشته د عزت تاج دی چې د صداقت له لارې تر‌لاسه کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_031.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1k8qbHAp5nhn9VZmg8c8z8ROZ5yvPoU5E&export=download', 1761237839, 1761237839),
(37384, 'Proverbs 16:32', 'Proverbs', 16, 32, 'څوک چې زر نه په قهریږي له یو قوي جنګیالي نه ښه دی د خپلې غوسې سړوونکی د یو ښار له فتح کوونکي نه بهتر دی.', 'چوک چې زر نه په قهریزی له یو قوی جنګیالی نه شه دی د خپلې غوسې سروونکی د یو شار له فتح کوونکی نه بهتر دی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_032.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1A7czkVqyT2zcgSryWKGZg5MC6bKEct8w&export=download', 1761237839, 1761237839),
(37385, 'Proverbs 16:33', 'Proverbs', 16, 33, 'انسان خو پچه میدان ته اچوي خو وروستنۍ پرېکړه د څښتن په لاس کې ده.', 'انسان خو پچه میدان ته اچوی خو وروستنی پرېکره د چشتن په لاس کې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/proverbs016_verse_033.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1qan094KhdorvF4XREzp2kXyqv2ttUU2q&export=download', 1761237839, 1761237839),
(37386, 'Genesis 40:1', 'Genesis', 40, 1, 'څه موده وروسته د مصر د پاچا یعنې فرعون د ساقیانو او نانوایانو د مشرانو څخه د پاچا په وړاندې غلطي وشوه.', 'چه موده وروسته د مصر د پاچا یعنې فرعون د ساقیانو او نانوایانو د مشرانو چخه د پاچا په وراندې غلطی وشوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_40_1.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
(37387, 'Genesis 40:2', 'Genesis', 40, 2, 'فرعون په دې دواړو درباریانو باندې په قهر شو', 'فرعون په دې دوارو درباریانو باندې په قهر شو', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_40_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37388, 'Genesis 40:3', 'Genesis', 40, 3, 'او هغوی یې په هغه زندان کې واچول چې د دربار د ساتونکو د قوماندان په کور کې ؤ یعنې په هماغه زندان کې چې یوسف په کې بندي ؤ.', 'او هغوی یې په هغه زندان کې واچول چې د دربار د ساتونکو د قوماندان په کور کې و یعنې په هماغه زندان کې چې یوسف په کې بندی و.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_40_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37389, 'Genesis 40:4', 'Genesis', 40, 4, 'هغوی زیات وخت په زندان کې تېر کړ او د ساتونکو قوماندان هغوی یوسف ته وسپارل او هغه د دوی خدمت کاوه.', 'هغوی زیات وخت په زندان کې تېر کر او د ساتونکو قوماندان هغوی یوسف ته وسپارل او هغه د دوی خدمت کاوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_40_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237839, 1761237839),
(37390, 'Genesis 40:5', 'Genesis', 40, 5, 'د ساقیانو او نانوایانو مشرانو چې په زندان کې وو، په یوه شپه دواړو خوب ولیده او هر یو خوب خپله معنی درلودله.', 'د ساقیانو او نانوایانو مشرانو چې په زندان کې وو، په یوه شپه دوارو خوب ولیده او هر یو خوب خپله معنی درلودله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Genesis_40_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237839, 1761237839),
