(37449, 'Isaiah 17:9', 'Isaiah', 17, 9, 'کله چې هغه ورځ راشي، د هغوی قوي ښارونه به شاړ او په ځنګلونو باندې بدل شي. هغه ښارونه به د هغو سیمو په شان شي چې خلکو د اسراییلو د حملې سره سم پرېښودل او هرڅه به وران او وېجاړ شي.', 'کله چې هغه ورج راشی، د هغوی قوی شارونه به شار او په جنګلونو باندې بدل شی. هغه شارونه به د هغو سیمو په شان شی چې خلکو د اسراییلو د حملې سره سم پرېشودل او هرچه به وران او وېجار شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah017_verse_009.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1sHNkcl9W50KkmIvmwnptO1aSNz1jhukx&export=download', 1761237839, 1761237839),
(37450, 'Isaiah 17:10', 'Isaiah', 17, 10, 'ای اسراییلو، تاسو هغه خدای هېر کړی دی چې تاسو یې ژغورلي یئ او د یاده مو وتلي دي چې هغه د یو زورور ګټ په شان ستاسو ساتنه کړې ده. د هغې په ځای، تاسو ښایسته باغونه کرلي دي چې د پردیو خدایانو عبادت په کې وکړئ.', 'ای اسراییلو، تاسو هغه خدای هېر کری دی چې تاسو یې ژغورلی یی او د یاده مو وتلی دی چې هغه د یو زورور ګت په شان ستاسو ساتنه کرې ده. د هغې په جای، تاسو شایسته باغونه کرلی دی چې د پردیو خدایانو عبادت په کې وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah017_verse_010.mp3', 'https://pashto-bible-search.vercel.app/api/audio-proxy?id=1qnN8H_fRZF5bN-sAIVidn-7TaeHyQ_Co&export=download', 1761237839, 1761237839),
(37451, 'Isaiah 17:11', 'Isaiah', 17, 11, 'خو حتی که په هماغه سهار کې چې تاسو هغه کرلي دي، هغه راشنه شي او وغوړیږي، بیا به هم هېڅ حاصل ورنه کړي. د دې په ځای به تاسو یوازې په غم او ناعلاجه درد اخته شئ.', 'خو حتی که په هماغه سهار کې چې تاسو هغه کرلی دی، هغه راشنه شی او وغوریزی، بیا به هم هېچ حاصل ورنه کری. د دې په جای به تاسو یوازې په غم او ناعلاجه درد اخته شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah017_verse_011.mp3', 'https://drive.google.com/uc?id=1-gPCh_7xBujLPMBIw_18rbKNf64p-o1n&export=download', 1761237839, 1761237839),
(37452, 'Isaiah 17:12', 'Isaiah', 17, 12, 'واورئ، بې شمېره قومونه د بحیرې په شان شور کوي، لکه د بحیرې د لویو لویو څپو د غړمبار په شان.', 'واوری، بې شمېره قومونه د بحیرې په شان شور کوی، لکه د بحیرې د لویو لویو چپو د غرمبار په شان.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah017_verse_012.mp3', 'https://drive.google.com/file/d/1tSXwoaWGkfxJSO8OzEe4eE3asmM-JVHh/preview', 1761237839, 1761237839),
(37453, 'Isaiah 17:13', 'Isaiah', 17, 13, 'قومونه لکه د تېزو څپو په شان غړمبار کوي، خو خدای هغوی رټي او هغوی لېرې تښتي، داسې تښتي لکه د باد په وخت کې د غونډیو په سر کې بوس او یا د تند باد په وخت کې چورلېدونکي بوټي.', 'قومونه لکه د تېزو چپو په شان غرمبار کوی، خو خدای هغوی رتی او هغوی لېرې تشتی، داسې تشتی لکه د باد په وخت کې د غوندیو په سر کې بوس او یا د تند باد په وخت کې چورلېدونکی بوتی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah017_verse_013.mp3', 'https://drive.google.com/file/d/1Mptm5ZeBopifuhB6mW9rXgXwsLZhkVi4/preview', 1761237839, 1761237839),
(37454, 'Isaiah 17:14', 'Isaiah', 17, 14, 'قومونه په ماښام کې د زیاتې وېرې سبب ګرځي، خو په سهار کې ورکیږي. دا د هغه چا تقدیر او قسمت دی چې زمونږ وطن لوټوي.', 'قومونه په ماشام کې د زیاتې وېرې سبب ګرجی، خو په سهار کې ورکیزی. دا د هغه چا تقدیر او قسمت دی چې زمونز وطن لوتوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/isaiah017_verse_014.mp3', 'https://drive.google.com/uc?id=1Kfor9ytgcIKXtwwL8s9hJg-jNYwBXyKd&export=download', 1761237839, 1761237839),
(37455, 'Songofsongs 3:1', 'Songofsongs', 3, 1, 'ټوله شپه کله چې زۀ په خپل کټ کښې پرته ومه، د چا سره چې زۀ مينه کوم ما د هغۀ لټون وکړونه، خو هغه رانۀ غلونه.', 'توله شپه کله چې زۀ په خپل کت کشې پرته ومه، د چا سره چې زۀ مینه کوم ما د هغۀ لتون وکرونه، خو هغه رانۀ غلونه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(37456, 'Songofsongs 3:2', 'Songofsongs', 3, 2, 'خو بيا ما خپل ځان ته ووئيل، زۀ به پاڅېږمه او ټول ښار به ولټومه، د هغه چا پسې به په چوکونو او سړکونو کښې وګرځېږمه چا سره چې زۀ مينه کومه. نو زۀ ورپسې ښۀ وګرځېدمه خو پېدا مې نۀ کړونه.', 'خو بیا ما خپل جان ته ووییل، زۀ به پاچېزمه او تول شار به ولتومه، د هغه چا پسې به په چوکونو او سرکونو کشې وګرجېزمه چا سره چې زۀ مینه کومه. نو زۀ ورپسې شۀ وګرجېدمه خو پېدا مې نۀ کرونه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(37457, 'Songofsongs 3:3', 'Songofsongs', 3, 3, 'چوکيدارانو زۀ ودرولمه، کله چې هغوئ په ښار کښې ګرځېدل. ما د هغوئ نه تپوس وکړلو، ”ولې تاسو هغه کس ليدلے دېنه چا سره چې زۀ مينه کومه؟“', 'چوکیدارانو زۀ ودرولمه، کله چې هغوی په شار کشې ګرجېدل. ما د هغوی نه تپوس وکرلو، ”ولې تاسو هغه کس لیدلے دېنه چا سره چې زۀ مینه کومه؟“', 'NT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(37458, 'Songofsongs 3:4', 'Songofsongs', 3, 4, 'نو چې د هغوئ نه لږ وړاندې لاړمه ما خپل جانان پېدا کړونه. هغه مې راټينګ کړونه او تلو ته مې پرې نۀ‎ ښودلونه او ما هغه د خپلې مور کور ته راوستونه هغې کوټې ته په کومه کښې چې زۀ د مور په ګېډه شوې ومه.', 'نو چې د هغوی نه لز وراندې لارمه ما خپل جانان پېدا کرونه. هغه مې راتینګ کرونه او تلو ته مې پرې نۀ‎ شودلونه او ما هغه د خپلې مور کور ته راوستونه هغې کوتې ته په کومه کشې چې زۀ د مور په ګېده شوې ومه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(37459, 'Songofsongs 3:5', 'Songofsongs', 3, 5, 'اے د يروشلم جينکو، ما سره ټينګه وعده وکړئينه، ترڅو چې مونږ پراتۀ يونه مونږ به نۀ په عذابوئينه.', 'اے د یروشلم جینکو، ما سره تینګه وعده وکریینه، ترچو چې مونز پراتۀ یونه مونز به نۀ په عذابویینه.', 'NT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839),
(37460, 'Songofsongs 3:6', 'Songofsongs', 3, 6, 'چې د لوګى د ستن په شان دے هغه څوک دېنه هغه زمونږ طرف ته راروان دېنه؟ چې فضا يې په مُر او لوبانو خوشبوداره کړې ده نه، او د سوداګرو په عطرو باندې خوشبوداره کړې ده نه؟', 'چې د لوګی د ستن په شان دے هغه چوک دېنه هغه زمونز طرف ته راروان دېنه؟ چې فضا یې په مر او لوبانو خوشبوداره کرې ده نه، او د سوداګرو په عطرو باندې خوشبوداره کرې ده نه؟', 'NT', 'afghan2023', 'afghan', '', '', 1761237839, 1761237839);